TABLES = ['material_binding_checks', 'material_uploads', 'material_versions', 'parsed_representations', 'material_fragments', 'material_ingestions', 'material_chunks', 'material_events', 'material_evidence']

def upgrade() -> None:
    for statement in STATEMENTS:
        op.execute(statement)


def downgrade() -> None:
    db = op.get_bind()
    if any(db.exec_driver_sql("SELECT EXISTS (SELECT 1 FROM cq_app." + name + " LIMIT 1)").scalar() for name in TABLES):
        raise RuntimeError("S04 downgrade would delete material evidence; use verified backup restore")
    for name in reversed(TABLES):
        op.execute("DROP TABLE cq_app." + name)
    op.execute("DROP FUNCTION cq_app.keep_material_artifact()")
